const findings=[];const q=s=>document.querySelector(s),click=s=>{const e=q(s);if(!e)throw Error('Missing '+s);e.click()},check=(name,ok)=>{findings.push({name,pass:!!ok});if(!ok)throw Error(name)};
for(const v of ['A','B','C','D']){click(`[role=tab][data-variant="${v}"]`);for(let n=0;n<6;n++){click(`[data-step="${n}"]`);check(`${v}${n}: heading`,!!q('h1'));check(`${v}${n}: no page overflow`,document.documentElement.scrollWidth<=window.innerWidth);check(`${v}${n}: one active stage`,document.querySelectorAll('[aria-current="step"]').length===1)}}
click('[role=tab][data-variant="A"]');click('[data-step="1"]');q('#rate').value=37;click('[data-action="connect"]');click('#scene [data-action="next"]');click('[data-action="payment"]');check('37% gives 2220',q('.metric').textContent.replace(/\s/g,'').includes('2220'));click('[data-action="payment"]');check('replay unchanged',q('.metric').textContent.replace(/\s/g,'').includes('2220'));click('[data-action="refund"]');check('refund voids',q('.metric').textContent.replace(/\s/g,'')==='0₽');click('[data-action="payment"]');check('replay cannot resurrect refunded commission',q('.metric').textContent.replace(/\s/g,'')==='0₽');click('[data-step="5"]');check('merchant enrollment link',q('#share-link').value.endsWith('/partners/join'));check('configured rate in invitation',q('#scene').textContent.includes('37%'));click('[data-step="3"]');click('[data-action="sent"]');check('manual sent state',q('tbody').textContent.includes('Отправлено'));click('[data-action="sent"]');
click('[role=tab][data-variant="B"]');click('[data-step="1"]');click('[data-action="join"]');check('consent blocks enrollment',!!q('#consent'));q('#consent').checked=true;click('[data-action="join"]');check('consent advances',q('h1').textContent.includes('принесла бонус'));click('[data-step="3"]');click('[data-action="apply"]');click('[data-action="apply"]');check('credit applies once',q('.stats').textContent.replace(/\s/g,'').includes('Использовано300₽'));click('[data-step="4"]');check('owner paywall explicit',q('#scene').textContent.includes('Владелец программы · смена роли'));click('[data-step="5"]');check('return to customer explicit',q('.work .eyebrow').textContent==='Клиент Proofwall');
click('[role=tab][data-variant="C"]');check('partner preview scoped',q('.preview').textContent.includes('Мои комиссии')&&!q('.preview').textContent.includes('Партнёры'));click('[data-step="3"]');click('[data-action="partner-sent"]');check('partner payout sent demo',q('#scene').textContent.includes('Отправлено 4 сентября'));click('[data-action="partner-sent"]');
click('[data-action="compare"]');check('comparison dialog opens',q('dialog').open);click('[data-choose="C"]');check('choice saved',q('#selection').textContent.includes('Выбран вариант C'));check('choice not PRD',JSON.parse(localStorage.getItem('n3-cjm-selection-v1')).prd_created===false);click('[data-action="clear"]');click('[data-action="mix"]');check('mix saved',q('#selection').textContent.includes('Сохранено сочетание'));click('[data-action="clear"]');click('[data-action="close"]');check('no default selection remains',localStorage.getItem('n3-cjm-selection-v1')===null);click('[role=tab][data-variant="A"]');return {viewport:{width:innerWidth,height:innerHeight},checks:findings.length,passed:findings.every(x=>x.pass),findings};
